SELECT import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, '{"pageId": "e0650000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 65, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "65", "printedPageNumber": 65, "pdfPageNumber": 448, "sequenceIndex": 55, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0650100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith—VI", "sourceIdentifier": "VI", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0650000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (b)—Reproach on Discard of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "band; and a person who hears the Azaan but does not go to the musjid for salaat with Jamaat.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650200-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith—VI", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650300-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "أخرج ابن مردويه عن كعب الحبر قال والذي أنزل التوراة على موسى والإنجيل على عيسى والزبور على داود والفرقان على محمد أنزلت هذه الآيات في الصلوات المكتوبات حيث ينادى بهن يوم يكشف عن ساق إلى قوله وهم سالمون، الصلوات الخمس إذا نودي بها وأخرج البيهقي في الشعب عن سعيد بن جبير قال الصلوات في الجماعات وأخرج البيهقي عن ابن عباس قال رجل يسمع الأذان فلا يجيب الصلاة كذا في الدر المنثور قلت وقام الآية يوم يكشف عن ساق ويدعون إلى السجود فلا يستطيعون خاشعة أبصارهم ترهقهم ذلة وقد كانوا يدعون إلى السجود وهم سالمون", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650400-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Ka''b Ahbaar says, \"By Him who revealed the Torah to Moosa, the Injeel to Eesa, the Psalms to Dawood (Alayhimus salaam), and the Qur''an on Muhammad (Sallallaho alaihe wasallam), the following verses were revealed in respect of saying fardh salaat in those places (mosques) where the Azaan is said: \"On the day when the glory of Saaq is revealed and they are ordered to prostrate themselves, but are not able, with eyes downcast, abasement stupifying them. And they had been summoned to prostrate themselves when they were quite hale and healthy.\" (LXVIII: 42 and 43).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}, {"id": "f0650500-0000-4000-8000-000000000001", "structuralNodeId": "b0650100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "The glory of Saaq is a particular type of glory to be displayed on the Day of Judgement. All Muslims will fall prostrate on seeing this glory, but there will be some whose backs will turn stiff and they will be unable to prostrate themselves. As to who these unlucky persons would be, different interpretations have been given by different commentators. According to this hadith, which is also corroborated by another narrated by Hadhrat Ibn Abbas (Radhiyallaho anho), those shall be the persons who were called for salaat with jamaat, but did not go for it.\n\nA few other interpretations of the same are given below:—\n\n1. Hadhrat Abu Sa''eed Khudri (Radhiyallaho anho) narrates on the authority of the Prophet (Sallallaho alaihe wasallam) that these shall be the persons who used to offer their salaat to be seen by other men.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 65"}]}'::jsonb);